const STORAGE_KEY = "demandes-front-office-v2";
const types = {
  "Assistance technique": { subtitle: "Précisez votre besoin d’assistance.", fields: `<label>Niveau sollicité <span>*</span><select name="supportLevel" required><option>Niveau 1</option><option>Niveau 2</option><option>Niveau 3</option></select></label><label>Produit ou service concerné <span>*</span><input name="product" required placeholder="Nom du produit ou service" /></label>` },
  "Demande de devis": { subtitle: "Décrivez la prestation à chiffrer.", fields: `<label>Nature du devis <span>*</span><select name="quoteNature" required><option value="">Sélectionner</option><option>Licences</option><option>Prestations</option><option>Formation</option><option>Autre</option></select></label><label>Quantité ou volume estimé <input name="quantity" placeholder="Ex. 250 utilisateurs" /></label>` },
  "Demande d’expertise": { subtitle: "Précisez le domaine et le résultat attendu.", fields: `<label>Domaine d’expertise <span>*</span><select name="expertiseArea" required><option value="">Sélectionner</option><option>Architecture</option><option>Optimisation</option><option>Migration</option><option>Montée de version</option><option>Autre</option></select></label><label>Modalité souhaitée <select name="deliveryMode"><option>À distance</option><option>Sur site</option><option>À définir</option></select></label>` },
  "Licences et souscriptions": { subtitle: "Indiquez l’opération et le périmètre concernés.", fields: `<label>Opération demandée <span>*</span><select name="licenseOperation" required><option value="">Sélectionner</option><option>Création</option><option>Renouvellement</option><option>Évolution du périmètre</option><option>Résiliation</option></select></label><label>Nombre de licences <span>*</span><input name="licenseCount" type="number" min="1" required placeholder="Ex. 120" /></label>` },
  "Déclaration de problème": { subtitle: "Décrivez le dysfonctionnement et son impact.", fields: `<label>Impact constaté <span>*</span><select name="impact" required><option value="">Sélectionner</option><option>Un utilisateur</option><option>Plusieurs utilisateurs</option><option>Un service complet</option><option>Établissement complet</option></select></label><label>Début du problème <input name="incidentDate" type="datetime-local" /></label>` },
  "Question diverse": { subtitle: "Indiquez le thème de votre question.", fields: `<label>Thème <span>*</span><select name="questionTheme" required><option value="">Sélectionner</option><option>Administratif</option><option>Contractuel</option><option>Facturation</option><option>Livraison</option><option>Autre</option></select></label><label>Réponse souhaitée par <select name="answerChannel"><option>Courriel</option><option>Téléphone</option></select></label>` }
};
const samples = [
  { id:"DEM-2026-0042",subject:"Renouvellement des licences collaboratives",type:"Licences et souscriptions",organization:"Métropole Nord",service:"Direction du numérique",requester:"Camille Martin",email:"camille.martin@example.fr",priority:"Haute",status:"En cours",created:"2026-09-08T09:14:00",description:"Renouvellement de 240 licences arrivant à échéance.",history:[{label:"Demande reçue et accusé envoyé",date:"8 sept. 2026 à 09:14"},{label:"Prise en charge par l’équipe dédiée",date:"8 sept. 2026 à 09:31"}]},
  { id:"DEM-2026-0041",subject:"Accompagnement à la montée de version",type:"Demande d’expertise",organization:"Ville de Montreuil",service:"Infrastructures",requester:"Alex Bernard",email:"alex.bernard@example.fr",priority:"Normale",status:"Nouvelle",created:"2026-09-07T15:42:00",description:"Expertise sur les prérequis et les étapes de la montée de version.",history:[{label:"Demande reçue et accusé envoyé",date:"7 sept. 2026 à 15:42"}]}
];
let requests = JSON.parse(localStorage.getItem(STORAGE_KEY) || "null") || samples;
let selectedType = "Assistance technique";
const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
const escapeHtml = (value="") => String(value).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]);
const formatDate = (value,withTime=false) => new Intl.DateTimeFormat("fr-FR",withTime?{dateStyle:"medium",timeStyle:"short"}:{day:"2-digit",month:"short",year:"numeric"}).format(new Date(value));
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(requests));}
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2500);}
function nextId(){const year=new Date().getFullYear();const high=requests.reduce((m,r)=>Math.max(m,Number(r.id.split("-").pop())||0),0);return `DEM-${year}-${String(high+1).padStart(4,"0")}`;}
function badge(status){const cls=status==="Nouvelle"?"new":status==="En cours"?"progress":"done";return `<span class="badge ${cls}">${escapeHtml(status)}</span>`;}
function selectType(type){selectedType=type;$("#request-type").value=type;$("#form-subtitle").textContent=types[type].subtitle;$("#specific-fields").innerHTML=types[type].fields;$$(".type-card").forEach(card=>card.classList.toggle("active",card.dataset.type===type));}
function showView(view){["create","follow","success"].forEach(name=>$("#"+name+"-view").classList.toggle("hidden",name!==view));$$('[data-view]').forEach(button=>button.classList.toggle("active",button.dataset.view===view&&button.classList.contains("nav-button")));if(view==="follow")renderList();window.scrollTo({top:0,behavior:"smooth"});}
function createRequest(form){const data=Object.fromEntries(new FormData(form));const now=new Date();const item={...data,id:nextId(),type:selectedType,status:"Nouvelle",created:now.toISOString(),history:[{label:"Demande reçue et accusé envoyé",date:formatDate(now,true)}]};requests.unshift(item);save();$("#nav-count").textContent=requests.length;$("#success-reference").textContent=item.id;$("#success-type").textContent=item.type;$("#success-date").textContent=formatDate(item.created,true);$("#success-email").textContent=item.email;showView("success");form.reset();selectType(selectedType);}
function renderList(){const query=$("#search").value.trim().toLowerCase();const status=$("#status-filter").value;const filtered=requests.filter(r=>(!query||`${r.id} ${r.subject} ${r.type}`.toLowerCase().includes(query))&&(!status||r.status===status));$("#request-list").innerHTML=filtered.map(r=>`<tr data-id="${r.id}"><td><span class="reference">${r.id}</span></td><td class="subject">${escapeHtml(r.subject)}<small>${escapeHtml(r.organization)}</small></td><td>${escapeHtml(r.type)}</td><td>${formatDate(r.created)}</td><td>${badge(r.status)}</td></tr>`).join("");$("#empty").classList.toggle("hidden",filtered.length>0);$$('[data-id]').forEach(row=>row.onclick=()=>openDetail(row.dataset.id));}
function openDetail(id){const r=requests.find(item=>item.id===id);if(!r)return;$("#detail-content").innerHTML=`<header class="detail-head"><button aria-label="Fermer">×</button>${badge(r.status)}<h2>${escapeHtml(r.subject)}</h2><p>${r.id} · créée le ${formatDate(r.created,true)}</p></header><div class="detail-body"><div class="detail-data"><div><small>Type</small><strong>${escapeHtml(r.type)}</strong></div><div><small>Priorité</small><strong>${escapeHtml(r.priority)}</strong></div><div><small>Établissement</small><strong>${escapeHtml(r.organization)}</strong></div><div><small>Service émetteur</small><strong>${escapeHtml(r.service)}</strong></div></div><h3>Description</h3><p>${escapeHtml(r.description)}</p><h3>Historique</h3><div class="history">${r.history.map(h=>`<div><strong>${escapeHtml(h.label)}</strong><small>${escapeHtml(h.date)}</small></div>`).join("")}</div></div>`;const dialog=$("#detail-dialog");dialog.showModal();$(".detail-head button").onclick=()=>dialog.close();}
$$('.type-card').forEach(card=>card.onclick=()=>selectType(card.dataset.type));
$$('[data-view]').forEach(button=>button.onclick=()=>showView(button.dataset.view));
$("#request-form").addEventListener("submit",event=>{event.preventDefault();if(event.currentTarget.reportValidity())createRequest(event.currentTarget);});
$("#request-form").addEventListener("reset",()=>setTimeout(()=>selectType("Assistance technique"),0));
$("#search").addEventListener("input",renderList);$("#status-filter").addEventListener("change",renderList);
$("#copy-reference").onclick=async()=>{try{await navigator.clipboard.writeText($("#success-reference").textContent);toast("Numéro copié.");}catch{toast("Sélectionnez le numéro pour le copier.");}};
$("#create-another").onclick=()=>showView("create");
$("#detail-dialog").addEventListener("click",event=>{if(event.target===$("#detail-dialog"))$("#detail-dialog").close();});
$("#nav-count").textContent=requests.length;selectType(selectedType);

